package cli

import (
	"context"
	"fmt"

	"charm.land/huh/v2"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/spf13/cobra"
)

// onDemandPluginInstall shares the normal install workflow, including index
// overrides, name/checksum validation and dependency confirmation. Tests replace
// it to exercise the prompt and dispatch without downloading real releases.
var onDemandPluginInstall = runRemoteInstall

func installMissingPlugin(ctx context.Context, rootCmd *cobra.Command, name string) (string, error) {
	if !interactive.CanPromptInteractively() {
		return "", fmt.Errorf("the entire-%s plugin is not installed; run 'entire plugin install %s' and retry", name, name)
	}
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("install plugin: %w", err)
	}
	confirmed := true
	form := NewAccessibleForm(huh.NewGroup(
		huh.NewConfirm().Title(fmt.Sprintf("Install the entire-%s plugin?", name)).Value(&confirmed),
	)).WithInput(rootCmd.InOrStdin()).WithOutput(rootCmd.ErrOrStderr())
	if err := form.RunWithContext(ctx); err != nil {
		return "", handleFormCancellation(rootCmd.ErrOrStderr(), "Install", err)
	}
	if !confirmed {
		fmt.Fprintln(rootCmd.ErrOrStderr(), "Install cancelled.")
		return "", nil
	}
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("install plugin: %w", err)
	}

	// Keep install progress off stdout: the original command may emit JSON or
	// be piped to another tool. Do not parse any of the plugin's arguments.
	cmd := newPluginInstallCmd()
	cmd.SetOut(rootCmd.ErrOrStderr())
	cmd.SetErr(rootCmd.ErrOrStderr())
	if err := onDemandPluginInstall(ctx, cmd, installSource{Kind: installFromIndex, Ref: name}, remoteInstallFlags{}); err != nil {
		return "", err
	}
	installed, err := FindInstalledPlugin(name)
	if err != nil {
		return "", err
	}
	if installed == nil {
		return "", fmt.Errorf("the entire-%s plugin was not installed; run 'entire plugin install %s' and retry", name, name)
	}
	// Execute the managed entry directly, even if the managed directory could
	// not be prepended to PATH at startup.
	return installed.Path, nil
}
// selfUpdatePluginName is the plugin that replaces the entire binary on
// disk (`entire upgrade` → entire-upgrade).
const selfUpdatePluginName = "upgrade"

// postPluginVersionCheck is a test seam for the version-check notice that
// fires after a successful plugin run.
var postPluginVersionCheck = versioncheck.CheckAndNotify

// MaybeRunPlugin returns (true, exitCode) when an external command was
// resolved and run. On launch failure (e.g. missing executable bit)
// returns (true, 1) after printing to stderr. On no-match returns
// (false, 0) so the caller can fall through to Cobra.
//
// Telemetry and the version-check notice mirror Cobra's PersistentPostRun
// behavior for built-ins: both fire only on a successful (exit-0) run.
func MaybeRunPlugin(ctx context.Context, rootCmd *cobra.Command, args []string) (handled bool, exitCode int) {
	binPath, pluginArgs, ok := resolvePlugin(rootCmd, args)
	if !ok {
		return false, 0
	}
	pluginName := args[0]
	if binPath == "" {
		var err error
		binPath, err = installMissingPlugin(ctx, rootCmd, pluginName)
		if err != nil {
			fmt.Fprintln(rootCmd.ErrOrStderr(), RenderUserFacingError(err))
			return true, 1
		}
		if binPath == "" {
			// The command was not executed because installation was declined.
			return true, 1
		}
		fmt.Fprintf(rootCmd.ErrOrStderr(), "Running plugin with command: %s\n", strings.Join(pluginArgs, " "))
	}
	exitCode = runPlugin(ctx, pluginName, binPath, pluginArgs)
	if exitCode == 0 {
		maybeTrackPluginInvocation(ctx, pluginName)
		// Stderr, matching the built-in PersistentPostRun: the plugin's own
		// stdout may be machine-readable and piped.
		//
		// Skipped after a self-update: this process still carries the
		// pre-upgrade compiled-in version, so the check would see itself as
		// outdated and prompt to redo the upgrade that just completed.
		if pluginName != selfUpdatePluginName {
			postPluginVersionCheck(ctx, os.Stderr, versioninfo.Version)
		}
	}
	return true, exitCode
}

// maybeTrackPluginInvocation fires telemetry only for plugins on the
// official allowlist. Third-party plugin names are never sent — see
// IsOfficialPlugin for the rationale.
func maybeTrackPluginInvocation(ctx context.Context, pluginName string) {
	if !IsOfficialPlugin(pluginName) {
		return
		cancel()
		<-sigChan
		dieFromSignal(sig)
	}()

	// Create and execute root command
	rootCmd := cli.NewRootCmd()

	// Make managed-installed plugins discoverable by the kubectl-style
	// dispatcher: prepend the managed bin dir to PATH before resolution.
	// Idempotent and silent on failure (managed installs simply won't be
	// found this run; PATH-installed plugins still work). The closure
	// restores PATH so built-in commands and their subprocesses don't
	// inherit the prepended dir. When a plugin runs, we skip the restore
	// — the os.Exit ends the process, and the plugin child intentionally
	// inherits the prepended PATH so it can spawn sibling managed plugins.
	restorePATH := cli.PrependPluginBinDirToPATH(ctx)

	if handled, code := cli.MaybeRunPlugin(ctx, rootCmd, os.Args[1:]); handled {
		cancel()
		os.Exit(code)
	}
	restorePATH()

	// Retired env vars fail every built-in command up front; a removed knob
	// must never be silently ignored. Plugins (above) are exempt — what they
	// read is their business.
	if err := api.RejectRemovedAuthEnv(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		cancel()
		os.Exit(1)
	}

	executed, err := rootCmd.ExecuteContextC(ctx)
	// The only place the logger is closed, and it must be here: cobra returns out
	// of Command.execute() as soon as RunE errors or required-flag validation
	// fails, both before its PersistentPostRun loop, so those paths would
	// otherwise exit with up to 8KB of buffered diagnostics unwritten. The logger
	// rides the executed command's context, where the root pre-run put it; a
	// failure raised before any pre-run carries none, and nothing logged yet.
	if l := logging.LoggerFromContext(executed.Context()); l != nil {
		_ = l.Close()
	}

	if err != nil {
		var silent *cli.SilentError

		switch {
		case errors.Is(err, context.Canceled) && procsignal.Load() != nil:
			// A signal cancelled the root context (our handler fired) or a
			// keyring read was aborted by Ctrl-C. Don't dump the raw
			// transport/keyring cancellation string ("...: context canceled",
			// "read access token: signal: interrupt") as if it were a failure
			// — die quietly by re-raising the signal that triggered it (see
			// dieFromSignal) so an enclosing `while ...; do entire; done` loop
			// actually breaks on a single Ctrl-C, and a SIGTERM shutdown still
			// exits 143.
			//
			// We gate on a signal having been recorded rather than on the
			// error type alone: a context.Canceled that arose without a signal
			// (e.g. an internally-cancelled sub-context) is a genuine error
			// and must fall through to normal reporting, not masquerade as a
			// user abort (which would also wrongly break an enclosing loop).
			// procsignal is the shared source of truth written both by the
			// handler above and by the keyring interrupt path; the latter
			// records the signal on this same goroutine before returning, so
			// this Load never races that write.
			cancel()
			dieFromSignal(terminatingSignal())
		case errors.As(err, &silent):
			// Command already printed the error
		case strings.Contains(err.Error(), "unknown command") || strings.Contains(err.Error(), "unknown flag"):
			showSuggestion(rootCmd, err)
		case isPositionalArgError(err):
			// Arg-count errors come from cobra's own validators (e.g.
			// cobra.ExactArgs) and surface as "accepts N arg(s), received M".
			// Show the failing subcommand's usage so the user sees what it
			// actually expects — rootCmd's usage isn't useful for a
			// subcommand-level arg mismatch. ExecuteContextC returns the
			// deepest matched command, which is the one that failed.
			showSuggestion(executed, err)
		default:
			// The choke point for everything a command returns rather than
			// prints itself: see cli.RenderUserFacingError for what it strips
			// and which other render sites exist.
			fmt.Fprintln(rootCmd.OutOrStderr(), cli.RenderUserFacingError(err))
		}

		cancel()
		os.Exit(1)
	}
		return nil
	}
	return installPlannedDeps(ctx, cmd, res.Metadata.Requires, idx, flags)
}

// installPlannedDeps plans, confirms once (apt-style), and executes
// dependency installs. The main plugin is already installed at this point,
// so a declined or non-confirmable plan degrades to a warning, not an
// error — doctor reports the gap afterwards.
func installPlannedDeps(ctx context.Context, cmd *cobra.Command, reqs []PluginRequirement, idx *PluginIndex, flags remoteInstallFlags) error {
	out, errOut := cmd.OutOrStdout(), cmd.ErrOrStderr()
	stopPlan := startPluginStep(ctx, "Checking plugin dependencies...")
	plan, err := PlanDependencyInstalls(ctx, reqs, idx)
	stopPlan()
	if err != nil {
		return fmt.Errorf("resolve dependencies: %w", err)
	}
	for _, w := range plan.Warnings {
		fmt.Fprintf(errOut, "Warning: %s\n", w)
	}
	if len(plan.Actions) == 0 {
		return nil
	}

	// No trust annotation per entry: a missing dependency resolves only
	// through the index, and an upgrade reinstalls from the source the user
	// already accepted at that plugin's own install time. There is no longer a
	// path by which an author-chosen URL can appear in this list.
	fmt.Fprintf(out, "\nThis plugin requires %d additional plugin(s):\n", len(plan.Actions))
	for _, a := range plan.Actions {
		switch {
		case a.Upgrade:
			fmt.Fprintf(out, "  %s  (installed %s, needs >= %s — will upgrade from %s)\n",
				a.Name, a.CurrentTag, a.MinVersion, redactURL(a.RepoURL))
		default:
			fmt.Fprintf(out, "  %s  (%s)\n", a.Name, redactURL(a.RepoURL))
		}
	}
	ok, err := confirmPluginAction(ctx, "Install them now?", flags.yes)
	switch {
	case errors.Is(err, errConfirmNeedsTerminal):
		// Non-interactive without --yes: the main install already
		// succeeded, so skip with a pointer instead of failing late.
		fmt.Fprintln(errOut, "Skipping dependency installs (no terminal for confirmation; re-run with --yes). 'entire plugin doctor' will report what's missing.")
		return nil
	case err != nil:
		// User abort prints "Dependency install cancelled." and falls
		// through to the skip note; real prompt failures are returned —
		// claiming "skipped" for an error the user never saw would be
		// misreporting.
		if cancelErr := handleFormCancellation(errOut, "Dependency install", err); cancelErr != nil {
			return cancelErr
		}
		fmt.Fprintln(errOut, "'entire plugin doctor' will report what's missing.")
		return nil
	case !ok:
		fmt.Fprintln(errOut, "Skipping dependency installs; 'entire plugin doctor' will report what's missing.")
		return nil
	}
	results, err := ExecuteDepPlan(ctx, plan, flags.allowUnverified)
	if err != nil {
		return err
	}
	for _, res := range results {
		fmt.Fprintf(out, "Installed dependency %q\n", res.Manifest.Name)
		if res.ReplacedFrom != "" {
			// The top-level install names what it replaced; this path must too,
			// and it matters more here. Dependency installs are confirmed once
			// as a batch, apt-style, and their repo URLs come from the catalog —
			// so an upgrade action can repoint a plugin the user had installed
			// from their own fork without ever naming the swap.
			fmt.Fprintf(errOut, "Warning: dependency %q replaced an existing install from %s\n",
				res.Manifest.Name, redactURL(res.ReplacedFrom))
		}
	}
	return nil
}

// errConfirmNeedsTerminal signals that a confirmation was required but no
// terminal is available and --yes was not passed. Callers decide whether
// that is fatal (untrusted install) or an informed skip (dependency
// installs after the main install already succeeded).
var errConfirmNeedsTerminal = errors.New("confirmation required but no terminal available; re-run with --yes")

// confirmPluginAction asks a yes/no question. assumeYes short-circuits;
// non-interactive runs without --yes return errConfirmNeedsTerminal rather
// than guessing. Prompt errors (including huh.ErrUserAborted on Ctrl+C/Esc)
// are returned raw for callers to map via handleFormCancellation.
func confirmPluginAction(ctx context.Context, prompt string, assumeYes bool) (bool, error) {
	if assumeYes {
		return true, nil
	}
	if !interactive.CanPromptInteractively() {
		return false, fmt.Errorf("%w (%s)", errConfirmNeedsTerminal, prompt)
	}
	confirmed := false
	form := NewAccessibleForm(huh.NewGroup(
		huh.NewConfirm().Title(prompt).Value(&confirmed),
	))
	if err := form.RunWithContext(ctx); err != nil {
		// %w keeps huh.ErrUserAborted reachable for handleFormCancellation.
		return false, fmt.Errorf("confirm: %w", err)
	}
	return confirmed, nil
}

// confirmInstallOrCancel asks an install confirmation and collapses the three
// non-proceed outcomes onto their shared handling. An abort (Ctrl+C/Esc) and a
// plain "no" both print "Install cancelled." and exit cleanly: the exit code
// must not depend on which one the user chose. Real prompt failures surface
// wrapped, and errConfirmNeedsTerminal propagates unchanged so the caller
// decides whether an unattended run may proceed without an answer.
func confirmInstallOrCancel(ctx context.Context, out io.Writer, prompt string, assumeYes bool) (bool, error) {
	ok, err := confirmPluginAction(ctx, prompt, assumeYes)
	switch {
	case errors.Is(err, errConfirmNeedsTerminal):
		return false, err
	case err != nil:
		return false, handleFormCancellation(out, "Install", err)
	case !ok:
		fmt.Fprintln(out, "Install cancelled.")
		return false, nil
	}
	return true, nil
}

// silencePluginCancel maps Ctrl+C-induced failures to a SilentError per the
// codebase convention (clean.go, session_tokens.go) — printing "context
// canceled" at a user who just interrupted a clone or download is noise.
// The ctx.Err() check matters because a killed git child surfaces as
// "signal: killed", not context.Canceled, when the cancellation raced the
// subprocess.
func silencePluginCancel(ctx context.Context, err error) error {
	if err == nil {
		return nil
	}
package cli

import (
	"context"
	"fmt"
	"io"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
)

type pluginProgressKey struct{}

// withPluginProgress opts the command into progress reporting. The context
// carries the writer through dependency installs without making library callers
// print to the process's terminal.
func withPluginProgress(ctx context.Context, out io.Writer) context.Context {
	return context.WithValue(ctx, pluginProgressKey{}, out)
}

// startPluginStep reports work before it starts. Stop the spinner before any
// prompt, warning or result is printed. The returned stop is idempotent so a
// deferred cleanup can also cover early returns.
func startPluginStep(ctx context.Context, message string) func() {
	out, ok := ctx.Value(pluginProgressKey{}).(io.Writer)
	if !ok {
		return func() {}
	}
	if IsAccessibleMode() || !interactive.ShouldStyle(out) {
		fmt.Fprintln(out, message)
		return func() {}
	}
	stop := startSpinner(out, message)
	var once sync.Once
	return func() { once.Do(func() { stop(false) }) }
}

